);
Reflect.get(obj2, "foo"); // "foobar"
// Proxy with get handler and receiver
const obj3 = new Proxy(
 { p: 1, foo: 2 },
 {
 get(t, prop, receiver) {
 return `${receiver[prop]}bar`;
 },
 },
);
Reflect.get(obj3, "foo", { foo: 3 }); // "3bar"
