 () => localStorage.getItem('draft') ?? ''
 );
 function handleChange(event) {
 const nextDraft = event.target.value;
 setDraft(nextDraft);
 localStorage.setItem('draft', nextDraft);
 }
 return (
 <label>
 Draft:
 <textarea
 value={draft}
 onChange={handleChange}
 rows={4}
 cols={30}
 />
 </label>
 );
}
export default function App() {
