import MyInput from './MyInput.js';
export default function Form() {
 const ref = useRef(null);
 function handleClick() {
 ref.current.focus();
 }
 return (
 <form>
 <MyInput label="Enter your name:" ref={ref} />
 <button type="button" onClick={handleClick}>
 Edit
 </button>
 </form>
 );
}
